mcp:tool-listener.mcp:parameters-schema:
{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"vuelo": {
			"type": "object",
			"description": "Vuelo elegido, copiado tal cual de la consulta del vuelo (vueloId, numeroVuelo, origen, destino, salida, llegada, precioPorPasajero, precioTotal...)"
		},
		"pasajeros": {
			"type": "integer",
			"minimum": 1,
			"maximum": 9,
			"description": "Número de pasajeros"
		},
		"titular": {
			"type": "object",
			"description": "Titular de la reserva",
			"properties": {
				"nombre": {
					"type": "string"
				},
				"apellidos": {
					"type": "string"
				},
				"email": {
					"type": "string"
				}
			},
			"required": [
				"nombre",
				"apellidos",
				"email"
			]
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"vuelo",
		"pasajeros",
		"titular"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"localizador": {
			"type": "string",
			"description": "Localizador de la reserva (6 caracteres)"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"localizador"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"localizador": {
			"type": "string",
			"description": "Localizador de la reserva"
		},
		"parking": {
			"type": "object",
			"description": "Reserva de parking de AENA, copiada tal cual (codigoReserva, producto, fechas, importe...)"
		},
		"pago": {
			"type": "object",
			"description": "Datos del pago, copiados tal cual (idPago, estado, urlPago, importe...)"
		},
		"estado": {
			"type": "string",
			"enum": [
				"PENDIENTE_PAGO",
				"CONFIRMADA",
				"CANCELADA"
			],
			"description": "Nuevo estado de la reserva"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"localizador"
	]
}
